import React, { useState, useRef, useEffect } from 'react';
import { getUsername } from '../../keycloak';
import './EventsHub.css';

const EventsHub = () => {
    const [userRoles, setUserRoles] = useState([]);
    const [showAddForm, setShowAddForm] = useState(false);
    const [activeMenu, setActiveMenu] = useState(null);
    const [newMaterial, setNewMaterial] = useState({ type: 'text', title: '', content: '', url: '', category: '' });
    const [notification, setNotification] = useState(null);
    const [showFeedbackForm, setShowFeedbackForm] = useState(false);
    const [feedbackText, setFeedbackText] = useState('');

    // Состояния для записи аудио
    const [isRecording, setIsRecording] = useState(false);
    const [mediaRecorder, setMediaRecorder] = useState(null);
    const [audioChunks, setAudioChunks] = useState([]);
    const [recordingTime, setRecordingTime] = useState(0);
    const recordingTimerRef = useRef(null);

    // Меню и их подменю
    const menuItems = [
        {
            id: 'about',
            title: '📖 О Нас',
            icon: '📖',
            color: '#3b82f6',
            isHighlighted: false,
            subItems: [
                { id: 'mission', title: 'Наша миссия', type: 'text' },
                { id: 'history', title: 'История проекта', type: 'text' },
                { id: 'team', title: 'Команда', type: 'text' },
                { id: 'values', title: 'Ценности', type: 'text' }
            ]
        },
        {
            id: 'important',
            title: '⭐ Важные материалы',
            icon: '⭐',
            color: '#f59e0b',
            isHighlighted: true,
            subItems: [
                { id: 'key-docs', title: 'Ключевые документы', type: 'text' },
                { id: 'announcements', title: 'Важные объявления', type: 'text' },
                { id: 'rules', title: 'Правила проекта', type: 'text' }
            ]
        },
        {
            id: 'interviews',
            title: '🎙️ Интервью',
            icon: '🎙️',
            color: '#8b5cf6',
            isHighlighted: false,
            subItems: [
                { id: 'expert', title: 'С экспертами', type: 'video' },
                { id: 'members', title: 'С участниками', type: 'audio' },
                { id: 'leaders', title: 'С лидерами мнений', type: 'video' }
            ]
        },
        {
            id: 'beginners',
            title: '🌱 Для новичков',
            icon: '🌱',
            color: '#10b981',
            isHighlighted: true,
            isSpecial: true,
            subItems: [
                { id: 'start-guide', title: 'С чего начать?', type: 'text' },
                { id: 'first-steps', title: 'Первые шаги', type: 'video' },
                { id: 'faq-beginners', title: 'Частые вопросы', type: 'text' },
                { id: 'mentors', title: 'Наставники', type: 'text' }
            ]
        },
        {
            id: 'reflections',
            title: '💭 Для размышлений',
            icon: '💭',
            color: '#06b6d4',
            isHighlighted: false,
            subItems: [
                { id: 'quotes', title: 'Цитаты', type: 'text' },
                { id: 'articles-think', title: 'Статьи', type: 'text' },
                { id: 'questions-deep', title: 'Глубокие вопросы', type: 'text' }
            ]
        },
        {
            id: 'participants',
            title: '🤝 От соучастников',
            icon: '🤝',
            color: '#ec4899',
            isHighlighted: false,
            subItems: [
                { id: 'stories', title: 'Истории успеха', type: 'text' },
                { id: 'experiences', title: 'Личный опыт', type: 'text' },
                { id: 'achievements', title: 'Достижения', type: 'text' }
            ]
        },
        {
            id: 'music',
            title: '🎵 Музыка',
            icon: '🎵',
            color: '#6366f1',
            isHighlighted: false,
            subItems: [
                { id: 'meditation-music', title: 'Для медитации', type: 'audio' },
                { id: 'inspirational', title: 'Вдохновляющая', type: 'audio' },
                { id: 'relax', title: 'Для релаксации', type: 'audio' }
            ]
        },
        {
            id: 'motivation',
            title: '⚡ Мотивация',
            icon: '⚡',
            color: '#f97316',
            isHighlighted: false,
            subItems: [
                { id: 'daily', title: 'Ежедневная мотивация', type: 'text' },
                { id: 'videos-mot', title: 'Мотивирующие видео', type: 'video' },
                { id: 'success', title: 'Истории успеха', type: 'text' }
            ]
        },
        {
            id: 'movies',
            title: '🎬 Фильмы',
            icon: '🎬',
            color: '#ef4444',
            isHighlighted: false,
            subItems: [
                { id: 'docs', title: 'Документальные', type: 'video' },
                { id: 'art-house', title: 'Артхаус', type: 'video' },
                { id: 'recommend', title: 'Рекомендации', type: 'text' }
            ]
        },
        {
            id: 'feedback',
            title: '💬 Отзывы и Предложения',
            icon: '💬',
            color: '#14b8a6',
            isHighlighted: false,
            isFeedback: true,
            subItems: [
                { id: 'reviews', title: 'Отзывы участников', type: 'text' },
                { id: 'suggestions', title: 'Предложения', type: 'text' },
                { id: 'wishes', title: 'Пожелания', type: 'text' }
            ]
        },
        {
            id: 'results',
            title: '📊 Результаты Тимошенко',
            icon: '📊',
            color: '#a855f7',
            isHighlighted: false,
            subItems: [
                { id: 'achievements-vs', title: 'Достижения', type: 'text' },
                { id: 'stats', title: 'Статистика', type: 'text' },
                { id: 'reports', title: 'Отчёты', type: 'text' }
            ]
        },
        {
            id: 'broadcasts',
            title: '📡 ЭФИРЫ',
            icon: '📡',
            color: '#dc2626',
            isHighlighted: true,
            isSpecial: true,
            subItems: [
                { id: 'live-broadcasts', title: 'Прямые эфиры', type: 'video' },
                { id: 'recordings-b', title: 'Записи эфиров', type: 'audio' },
                { id: 'schedule', title: 'Расписание', type: 'text' }
            ]
        },
        {
            id: 'challenge',
            title: '🏆 Годовой челлендж',
            icon: '🏆',
            color: '#eab308',
            isHighlighted: true,
            subItems: [
                { id: 'rules-ch', title: 'Правила', type: 'text' },
                { id: 'progress', title: 'Прогресс', type: 'text' },
                { id: 'results-ch', title: 'Результаты', type: 'text' },
                { id: 'leaderboard', title: 'Таблица лидеров', type: 'text' }
            ]
        }
    ];

    // Получаем роль из localStorage
    const demoRole = localStorage.getItem('demoRole');
    const isAdmin = demoRole === 'admin';
    const currentUser = getUsername();

    useEffect(() => {
        const savedRoles = localStorage.getItem('demoRole');
        let roles = [];
        if (savedRoles === 'admin') {
            roles = ['admin', 'user'];
        } else if (savedRoles === 'user') {
            roles = ['user'];
        }
        setUserRoles(roles);
    }, []);

    // Функция для определения типа файла
    const getFileType = (file) => {
        if (file.type.startsWith('audio/')) return 'audio';
        if (file.type.startsWith('video/')) return 'video';
        if (file.type.startsWith('image/')) return 'photo';
        return 'text';
    };

    // Обработка загрузки файла
    const handleFileUpload = (e) => {
        const file = e.target.files[0];
        if (!file) return;

        const fileType = getFileType(file);
        const url = URL.createObjectURL(file);

        setNewMaterial({
            ...newMaterial,
            type: fileType,
            url: url,
            title: newMaterial.title || file.name.replace(/\.[^/.]+$/, '')
        });
    };

    // Функции для записи аудио
    const startRecording = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            const recorder = new MediaRecorder(stream);
            const chunks = [];

            recorder.ondataavailable = (e) => {
                chunks.push(e.data);
            };

            recorder.onstop = async () => {
                const audioBlob = new Blob(chunks, { type: 'audio/webm' });
                const audioUrl = URL.createObjectURL(audioBlob);

                setNewMaterial({
                    ...newMaterial,
                    type: 'audio',
                    url: audioUrl,
                    title: newMaterial.title || `Аудиозапись ${new Date().toLocaleString()}`
                });

                setAudioChunks([]);
                stream.getTracks().forEach(track => track.stop());
            };

            recorder.start();
            setMediaRecorder(recorder);
            setIsRecording(true);

            setRecordingTime(0);
            recordingTimerRef.current = setInterval(() => {
                setRecordingTime(prev => prev + 1);
            }, 1000);

        } catch (err) {
            console.error('Ошибка доступа к микрофону:', err);
            alert('Не удалось получить доступ к микрофону. Проверьте разрешения.');
        }
    };

    const stopRecording = () => {
        if (mediaRecorder && isRecording) {
            mediaRecorder.stop();
            setIsRecording(false);
            if (recordingTimerRef.current) {
                clearInterval(recordingTimerRef.current);
            }
        }
    };

    const formatRecordingTime = (seconds) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    };

    // Отправка отзыва/предложения
    const handleSendFeedback = () => {
        if (!feedbackText.trim()) {
            alert('Введите ваш отзыв или предложение');
            return;
        }

        const feedback = {
            id: Date.now(),
            type: 'feedback',
            text: feedbackText.trim(),
            author: currentUser,
            date: new Date().toISOString().split('T')[0],
            time: new Date().toLocaleTimeString(),
            isRead: false,
            category: activeMenu === 'feedback' ? newMaterial.category || 'general' : 'general'
        };

        // Сохраняем отзыв в localStorage
        const savedFeedbacks = localStorage.getItem('userFeedbacks');
        let feedbacks = savedFeedbacks ? JSON.parse(savedFeedbacks) : [];
        feedbacks.unshift(feedback);
        localStorage.setItem('userFeedbacks', JSON.stringify(feedbacks));

        // Также добавляем как вопрос в систему вопросов с пометкой
        const savedQuestions = localStorage.getItem('userQuestions');
        let questions = savedQuestions ? JSON.parse(savedQuestions) : [];

        const questionFeedback = {
            id: Date.now(),
            question: `📝 ОТЗЫВ/ПРЕДЛОЖЕНИЕ от ${currentUser}: ${feedbackText.substring(0, 100)}${feedbackText.length > 100 ? '...' : ''}`,
            fullText: feedbackText,
            answer: '',
            author: currentUser,
            date: new Date().toISOString().split('T')[0],
            isAnswered: false,
            isFeedback: true,
            feedbackId: feedback.id
        };

        questions.unshift(questionFeedback);
        localStorage.setItem('userQuestions', JSON.stringify(questions));

        setNotification('Ваш отзыв отправлен администратору!');
        setTimeout(() => setNotification(null), 3000);

        setFeedbackText('');
        setShowFeedbackForm(false);
        setActiveMenu(null);
    };

    const handleAddMaterial = () => {
        if (!isAdmin) {
            alert('Только администратор может добавлять материалы');
            return;
        }

        if (!newMaterial.title) {
            alert('Заполните заголовок');
            return;
        }

        // Сохраняем материал в архив
        const savedArchive = localStorage.getItem('archiveMaterials');
        let archive = savedArchive ? JSON.parse(savedArchive) : [];

        const material = {
            id: Date.now(),
            ...newMaterial,
            date: new Date().toISOString().split('T')[0],
            time: new Date().toLocaleTimeString(),
            author: 'Admin',
            menuId: activeMenu
        };

        archive.unshift(material);
        localStorage.setItem('archiveMaterials', JSON.stringify(archive));

        setNotification(`Материал "${newMaterial.title}" добавлен в архив!`);
        setTimeout(() => setNotification(null), 3000);

        setNewMaterial({ type: 'text', title: '', content: '', url: '', category: '' });
        setShowAddForm(false);
        setActiveMenu(null);
    };

    return (
        <div className="events-hub">
            {/* Уведомление */}
            {notification && (
                <div className="hub-notification">
                    <div className="notification-content">
                        <div className="notification-icon">✅</div>
                        <div className="notification-text">
                            <strong>{notification.includes('отправлен') ? '📨 Отправлено!' : '📚 Добавлено!'}</strong>
                            <span>{notification}</span>
                        </div>
                        <div className="notification-close" onClick={() => setNotification(null)}>✕</div>
                    </div>
                </div>
            )}

            {/* Модальное окно добавления материала (только для админа) */}
            {showAddForm && isAdmin && (
                <div className="add-material-modal">
                    <div className="modal-container">
                        <div className="modal-header">
                            <h3>📝 Добавить материал в "{menuItems.find(m => m.id === activeMenu)?.title}"</h3>
                            <button className="modal-close" onClick={() => {
                                setShowAddForm(false);
                                setActiveMenu(null);
                            }}>✕</button>
                        </div>
                        <div className="modal-body">
                            <input
                                type="text"
                                className="material-title-input"
                                placeholder="Заголовок материала"
                                value={newMaterial.title}
                                onChange={(e) => setNewMaterial({...newMaterial, title: e.target.value})}
                            />
                            <textarea
                                className="material-content-input"
                                placeholder="Описание материала..."
                                value={newMaterial.content}
                                onChange={(e) => setNewMaterial({...newMaterial, content: e.target.value})}
                                rows="4"
                            />

                            <div className="media-controls">
                                <div className="media-buttons">
                                    <label className="attach-button">
                                        📎 Прикрепить файл
                                        <input
                                            type="file"
                                            accept="audio/*,video/*,image/*"
                                            onChange={handleFileUpload}
                                            style={{ display: 'none' }}
                                        />
                                    </label>

                                    <button
                                        className={`mic-button ${isRecording ? 'recording' : ''}`}
                                        onClick={isRecording ? stopRecording : startRecording}
                                        type="button"
                                    >
                                        {isRecording ? '⏹️ Остановить запись' : '🎤 Записать аудио'}
                                    </button>
                                </div>

                                {isRecording && (
                                    <div className="recording-indicator">
                                        <span className="recording-dot">🔴</span>
                                        <span className="recording-time">Запись: {formatRecordingTime(recordingTime)}</span>
                                    </div>
                                )}

                                {newMaterial.url && (
                                    <div className="attached-file">
                                        <span className="file-info">
                                            {newMaterial.type === 'audio' ? '🎵 Аудиофайл' :
                                                newMaterial.type === 'video' ? '🎬 Видеофайл' :
                                                    newMaterial.type === 'photo' ? '📷 Фото' : '📄 Документ'}
                                        </span>
                                        <button
                                            className="remove-file"
                                            onClick={() => setNewMaterial({...newMaterial, url: '', type: 'text'})}
                                        >
                                            ✕
                                        </button>
                                    </div>
                                )}
                            </div>

                            <button className="publish-btn" onClick={handleAddMaterial}>
                                📤 Добавить в архив
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Модальное окно для отзыва/предложения */}
            {showFeedbackForm && (
                <div className="add-material-modal">
                    <div className="modal-container">
                        <div className="modal-header">
                            <h3>💬 Ваш отзыв или предложение</h3>
                            <button className="modal-close" onClick={() => {
                                setShowFeedbackForm(false);
                                setActiveMenu(null);
                            }}>✕</button>
                        </div>
                        <div className="modal-body">
                            <textarea
                                className="feedback-input"
                                placeholder="Поделитесь своим мнением, предложением или отзывом о проекте..."
                                value={feedbackText}
                                onChange={(e) => setFeedbackText(e.target.value)}
                                rows="6"
                            />
                            <div className="feedback-hint">
                                <p>💡 Ваш отзыв будет отправлен администратору и появится в разделе "Вопросы" с пометкой "Отзыв/Предложение"</p>
                            </div>
                            <button className="publish-btn" onClick={handleSendFeedback}>
                                📤 Отправить отзыв
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Круговое меню */}
            <div className="circular-menu">
                <div className="menu-title">
                    <h2>📚 Библиотека материалов</h2>
                    <p>Наведите на раздел, чтобы увидеть доступные материалы</p>
                </div>

                <div className="menu-items-container">
                    {menuItems.map((item, index) => {
                        const isActive = activeMenu === item.id;

                        return (
                            <div
                                key={item.id}
                                className={`menu-item ${isActive ? 'active' : ''} ${item.isHighlighted ? 'highlighted' : ''} ${item.isSpecial ? 'special' : ''}`}
                                style={{
                                    '--color': item.color,
                                    '--delay': `${index * 0.05}s`
                                }}
                                onMouseEnter={() => setActiveMenu(item.id)}
                                onMouseLeave={() => setActiveMenu(null)}
                            >
                                <div className="menu-icon" style={{ background: `linear-gradient(135deg, ${item.color}, ${item.color}dd)` }}>
                                    <span className="icon">{item.icon}</span>
                                    <span className="title">{item.title}</span>
                                    {item.isHighlighted && <span className="highlight-badge">⭐</span>}
                                    {item.isSpecial && <span className="special-badge">🔥</span>}
                                </div>

                                {isActive && (
                                    <div className="submenu">
                                        <div className="submenu-header" style={{ background: item.color }}>
                                            <span>{item.icon}</span>
                                            <span>{item.title}</span>
                                        </div>
                                        <div className="submenu-items">
                                            {item.subItems.map(sub => (
                                                <div key={sub.id} className="submenu-item">
                                                    <span className="sub-icon">
                                                        {sub.type === 'audio' ? '🎵' :
                                                            sub.type === 'video' ? '🎬' :
                                                                sub.type === 'photo' ? '📷' : '📄'}
                                                    </span>
                                                    <span className="sub-title">{sub.title}</span>
                                                    {isAdmin && !item.isFeedback && (
                                                        <button
                                                            className="add-material-btn"
                                                            onClick={() => {
                                                                setActiveMenu(item.id);
                                                                setNewMaterial({...newMaterial, category: sub.id});
                                                                setShowAddForm(true);
                                                            }}
                                                        >
                                                            +
                                                        </button>
                                                    )}
                                                </div>
                                            ))}
                                        </div>
                                        {isAdmin && !item.isFeedback && (
                                            <div className="submenu-footer">
                                                <button
                                                    className="add-any-material"
                                                    onClick={() => {
                                                        setActiveMenu(item.id);
                                                        setShowAddForm(true);
                                                    }}
                                                >
                                                    ➕ Добавить материал в этот раздел
                                                </button>
                                            </div>
                                        )}
                                        {item.isFeedback && (
                                            <div className="submenu-footer">
                                                <button
                                                    className="add-any-material feedback-btn"
                                                    onClick={() => {
                                                        setActiveMenu(item.id);
                                                        setShowFeedbackForm(true);
                                                    }}
                                                >
                                                    💬 Оставить отзыв или предложение
                                                </button>
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    );
};

export default EventsHub;
